# Fixed reference example. Playground inputs do not update this sample.
curl --request POST \
  --url https://api.aisa.one/apis/v1/you-com/web-search-full-page-cache \
  --header 'Authorization: Bearer <token>' \
  --header 'Content-Type: application/json' \
  --data '{
  "count": 1,
  "extraction": {
    "extraction_mode": "full_page",
    "extraction_source": "cache"
  },
  "query": "nike"
}'

